<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Parent/Guardian');$q=db()->prepare('SELECT s.id,u.name,s.enrollment_no FROM parent_students ps JOIN parents p ON p.id=ps.parent_id JOIN students s ON s.id=ps.student_id JOIN users u ON u.id=s.user_id WHERE p.user_id=?');$q->execute([actor_id()]);$kids=$q->fetchAll();page_top('Child Fees');foreach($kids as $k){$f=db()->prepare('SELECT category,amount,discount,paid_amount,due_date,status FROM student_fees WHERE student_id=?');$f->execute([$k['id']]);?><div class='card p-3 mb-3'><h5><?=e($k['name'])?></h5><table class='table'><tr><th>Category</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Due</th></tr><?php foreach($f as $r):?><tr><td><?=e($r['category'])?></td><td>₹<?=e(number_format($r['amount']-$r['discount'],2))?></td><td>₹<?=e(number_format($r['paid_amount'],2))?></td><td>₹<?=e(number_format(max(0,$r['amount']-$r['discount']-$r['paid_amount']),2))?></td><td><?=e($r['due_date'])?></td></tr><?php endforeach;?></table></div><?php }page_bottom();
